      5'd1: o_t = {1'd0, o_yx[12:4]};
      5'd2: o_t = {2'd0, o_yx[12:5]};
      5'd3: o_t = {3'd0, o_yx[12:6]};
      5'd4: o_t = {4'd0, o_yx[12:7]};
      5'd5: o_t = {5'd0, o_yx[12:8]};
      5'd6: o_t = {6'd0, o_yx[12:9]};
      5'd7: o_t = {7'd0, o_yx[12:10]};
      5'd8: o_t = {8'd0, o_yx[12:11]};
      5'd9: o_t = {9'd0, o_yx[12:12]};
      default: o_t = 10'd0;
    endcase
  end
  wire [10:0] o_tp1 = {1'b0, o_t} + 11'd1;
  wire [9:0] o_yr  = o_tp1[10:1];
  wire [8:0] y_c = under ? 9'd0 : o_yr[8:0];

  // output register (loaded when a result is valid, held otherwise)
  always @(posedge clk) begin
    if (v_r) y <= y_c;
  end
endmodule
